    for char in s:
        if char == '[':
            if stack and stack[-1] == ':':
                stack.pop()
                current_length += 2
            else:
                return -1
        elif char == ']':
            if stack and stack[-1] == ':':
                stack.pop()
                current_length += 2
                max_length = max(max_length, current_length)
                current_length = 0
            else:
                return -1
        elif char == ':' and len(stack) > 0 and stack[-1] != ':':
            stack.append(char)
            current_length += 1
        elif char == '|' and len(stack) > 0 and stack[-1] == ':':
            stack.append(char)
            current_length += 1
        else:
            return -1

    if stack or current_length > 0:
        return -1

    return max_length

